:root:is([data-finish="midnight-black"],[data-finish="titanium-graphite"]) #app #newsroom .company-followup-preview{--text-primary:#edf1fa;--text-secondary:#bcc8da;--surface-panel:#202633;--surface-raised:#293243;--border-strong:#73829a;--followup-selected-bg:#383253;--followup-selected-border:#b9a8ff;background:var(--surface-panel)!important;color:var(--text-primary)}
:root:is([data-finish="midnight-black"],[data-finish="titanium-graphite"]) #app #newsroom .company-followup-preview :is(.company-followup-panels,.company-followup-rule,.company-followup-channels label,.followup-empty,.agent-thread article,.issue-brief,.followup-issue,.company-followup-cycle em){background:var(--surface-raised);border-color:var(--border-strong);color:var(--text-primary)}
:root:is([data-finish="midnight-black"],[data-finish="titanium-graphite"]) #app #newsroom .company-followup-preview :is(h3,h4,b,p,small,em,.company-followup-cycle span,.company-followup-channels b,.company-followup-channels em,.followup-panel-head span){color:var(--text-primary)}



#app #diet #dietStats .stat{background:var(--surface-raised)!important;color:var(--text-primary)!important}
